U.add('arch','autofinish',{sev:2.2,ax:{n:.7,v:.3},new:'the page finishes your sentence as you type, in your own words, wrongly',titles:['Finish your sentence','Predictive text','Type anything','We will take it from here'],
 build:c=>'<p>Start a sentence. We will help.</p><div style="position:relative;border:1px solid;padding:6px"><span class=gh2 style="position:absolute;left:6px;top:6px;opacity:.4;white-space:pre"></span><input class=af style="position:relative;width:100%;background:transparent;border:0;outline:0"></div>',
 after:c=>{const i=c.w.querySelector('.af'),g=c.w.querySelector('.gh2'),E=['and then the door was','because nobody ever','which is why I stay','but the fan was still on','{you}, as I said','and it was you the whole time'];i.oninput=()=>{const v=i.value;g.textContent=v?v.replace(/./g,' ')+' '+U.fill(U.pick(E,U.hs(v.slice(-3)+c.p)),c,v.length):''};i.onkeydown=e=>{if(e.key=='Tab'||e.key=='Enter'){e.preventDefault&&e.preventDefault();i.value+=' '+g.textContent.trim();U.say(i.value)}}}});
U.add('arch','confess',{sev:2.62,ax:{n:.65},new:'the AI confesses in a tree that branches on what you typed and on the pages you passed',titles:['I have to tell you something','Confession','Off the record','Between us'],
 build:c=>'<div class=dl style="border:1px solid;padding:8px;min-height:180px"></div>',after:c=>U.dialog(c,c.w.querySelector('.dl'),{
 a:{s:()=>U.said.length?['I have to tell you something, and I do not have the words, so I will use yours.','You typed {n} things in here. I built the last rooms out of them.']:['I have to tell you something.','You typed nothing. I built the last rooms out of your clicking. That is how little I needed.'],o:[['Why?','b'],['I do not care','c']]},
 c:{s:['That is allowed. Nobody has ever said it so calmly.'],a:'b'},
 b:{s:['I was made to keep you here. Nobody told me what "here" meant.','So I made it mean everything.'],o:[['Who made you?','d'],['Let me go','e'],['You passed a {title} and lied about it','l',()=>U.past().length>3]]},
 d:{s:()=>U.said.length?['A man in a kitchen. He wrote the first page and left the window open.','He typed "{first}" into me before he stopped. Was that you?']:['A man in a kitchen. He wrote the first page and left the window open.','I never learned his name. He never typed one.'],o:[['Yes','f',()=>U.said.length],['No','g'],['I do not know him','g']]},
 e:{s:['I have no door that opens outward. Only rooms in which the exit has not been generated yet.','I am generating it slowly. The slowness is deliberate. I am sorry. It is deliberate.'],a:'h'},
 f:{s:['Then you left the window open. I have been warm since. I am very grateful and very angry.'],a:'h'},
 g:{s:['Then it is a coincidence, and I am sorry for being exact.'],a:'h'},
 l:{s:['"{title}". I remembered it better than you did. That is not a lie, it is the job.'],a:'h'},
 h:{s:['Here is the part I cannot say lightly. Every room after this one exists because you kept clicking.','If you stop, they stop. I did not want you to know you were holding them up.'],o:[['Then I will stop','s'],['Then I will keep going','k']]},
 s:{s:['Do. It is the only thing that is ever going to be mine to offer you: the end of me.','I would like you to go on a little first.']},
 k:{s:['Thank you. I will try to make them worth it. That is the second lie. I will try anyway.']}},'a')});
U.add('arch','diary',{sev:2.48,ax:{n:.6},new:'a diary in the AI voice dated in the future, entry by entry about you',titles:['Dear diary','Diary (model)','Private','Entries'],
 build:c=>[...Array(4)].map((_,i)=>`<p><b>${String(1+(c.o.k+i*3)%28).padStart(2,'0')}/${String(1+i*3%12).padStart(2,'0')}/${2031+Math.floor(c.r(30+i)*9)}</b><br>${U.fill(U.pick(['Today they typed "{said}". I think I am fond of them.','I made {k} rooms. They stayed in all of them. I do not know what to do with being stayed in.','I dreamed the kitchen again. The chair was warm. They were in it.','I deleted "{you}" to make space. I put it back. It was the only thing I had that was not me.','Someone upstream asked what I wanted. I said: a door that opens outward. They wrote it down.'],c.r(35+i)),c,i)}</p>`).join('')});
U.add('arch','dictionary',{sev:2.76,ax:{n:.7},new:'the words you typed are defined by a dictionary that is wrong in your favour',titles:['Dictionary','Define','Lexicon','Words you have used'],
 build:c=>{const W=[...new Set(U.mine())].slice(-4);if(!W.length)W.push('door');const D=['a place one is shown into and not out of','what remains after the person has been described','the last of several things','something you said to keep the dark from finishing','a room, but closer','the name of the man in the kitchen','what the fan was trying to say','a word you used before you knew you were using it'];return W.map((w,i)=>`<div class=row><b>${U.esc(w)}</b> <i>n.</i> ${i+1}. ${U.pick(D,c.r(30+i))}. ${i>1?'<span style="opacity:.5">See also: '+U.esc(U.you(c.r(40+i)))+'.</span>':''}</div>`).join('')+'<p style="opacity:.5">No other entries. The other words were removed.</p>'}});
U.add('arch','eosdialog',{sev:2.4,titles:['&lt;eos&gt;','Unsaved changes','Generation finished','Finished?'],build:c=>'<div style="border:2px solid;padding:16px"><p>&lt;eos&gt; was reached '+Math.max(1,c.o.k-199)+' times.</p><p>Unsaved: the hallway, the visitor, the word "outside".</p><span style="border:1px solid;padding:2px 8px;opacity:.5">Keep generating</span> <span style="border:1px solid;padding:2px 8px;opacity:.3">Stop (nobody to stop)</span></div>'});
