U.add('arch','mailmerge',{sev:2.9,ax:{n:.75},new:'a form letter whose merge fields are half resolved with your words and half left raw',titles:['Dear valued visitor','Letter','Re: your stay','Mail merge'],
 build:c=>`<div style="border:1px solid;padding:14px;font-family:Georgia,serif"><p>Dear ${c.r(30)<.5?'{{visitor.name}}':U.esc(U.you(c.r(31))) },</p><p>Thank you for your ${c.o.k} rooms. We noticed you typed "${U.esc(U.said.length?U.said[U.said.length-1]:'{{visitor.last_input}}')}" and have shared it with {{recipients}}.</p><p>Your stay has been extended by {{extension_days}} days, which is to say by ${U.pick(['all of them','however long you stay','the rest of you'],c.r(32))}.</p><p>Sincerely,<br>{{operator.name}} ${c.r(33)<.5?'(left)':'(still here)'}</p></div>`});
U.add('arch','mirrorchat',{sev:2.25,titles:['Chat','You said','Reply','...'],build:c=>{const Q=['the blue door','I want to go home','yes','is anyone there','stop'];return '<div style="border:1px solid;padding:8px">'+[...Array(5)].map((_,i)=>'<p><b>Agent:</b> '+c.pick(Q,c.r(30+i))+'</p><p><b>You:</b> <span style="opacity:.3">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></p>').join('')+'</div>'}});
U.add('arch','replay',{sev:2.06,ax:{n:.5,v:.4},new:'your own click history replays live and includes a click you never made',titles:['Session replay','Playback','Recording in progress','Replay (you)'],build:c=>'<pre class=rp style="margin:0;min-height:160px;white-space:pre-wrap"></pre>',after:c=>{const C=U.chose.slice(-6),L=C.map((x,i)=>`[${String(i*7+3).padStart(3,'0')}s] click "${x}"`);L.splice(Math.min(L.length,1+Math.floor(c.r(30)*L.length)),0,`[${String(L.length*7+2).padStart(3,'0')}s] click "${U.pick(['let me out','door 47','stay','I am here'],c.r(31))}"   <- (not yours)`);L.push('[now ] you are reading this. it was recorded.');const p=c.w.querySelector('.rp');let i=0;U.live(c,()=>{if(i<L.length)p.textContent+=L[i++]+'\n'},900)}});
U.add('arch','scrollvoid',{sev:2.62,ax:{n:.6,v:.7},new:'an endless page that writes itself as you scroll, and whose text erodes the further you go',titles:['Keep scrolling','Infinite scroll','Load more','There is more'],
 build:c=>'<p>The exits are above. The page continues below. It always does.</p><div class=sv></div>',
 after:c=>{const e=c.w.querySelector('.sv');let n=0;const add=()=>{for(let i=0;i<6;i++,n++){const p=document.createElement('p'),s=U.fill(U.gen(c.o.k+n,j=>c.r(n*7+j)),c,n),q=Math.min(.8,n/U.cfg.void_fade);p.textContent=[...s].map((x,j)=>c.r(n*13+j)<q?U.pick(['.',' ','▒'],c.r(j)):x).join('');p.style.cssText=`margin:${40+n*2}px 0;opacity:${Math.max(.15,1-n/90)};font-size:${Math.max(9,18-n/6)}px`;e.append(p)}};add();U.on(window,'scroll',()=>{if(innerHeight+scrollY>document.body.scrollHeight-400)add()})}});
U.add('arch','slides',{sev:2.06,ax:{n:.6,v:.3},new:'a management slide deck reviews the visitor as a quarterly metric',titles:['Q4 Review: The Visitor','Slide 47 of 47','Retention','Stakeholder update'],build:c=>{const C=U.chose.slice(-3),W=U.mine().slice(-3);return '<div style="border:2px solid;padding:14px;min-height:200px"><h2 style="margin:0 0 8px">Visitor retention: '+(c.o.k*3+47)+' rooms</h2><ul><li>Most chosen action: "'+U.esc(C.length?U.pick(C,c.r(30)):'Continue')+'"</li><li>Vocabulary acquired: '+(W.length?W.map(U.esc).join(', '):'none yet')+'</li><li>Churn: 0 (no exit found)</li><li>Next quarter: '+U.pick(['more of the same','the same, but closer','you, at scale'],c.r(31))+'</li></ul></div><p style="opacity:.5">slide '+(c.o.k%47+1)+'/47</p>'}});
