U.add('gl','swallow',{sev:2.62,ax:{v:.65},new:'the page is eaten from its edges by an animated clip-path over a minute',apply:c=>{c.w.style.transition=`clip-path ${U.cfg.swallow_s}s linear`;c.w.style.clipPath='inset(0 0 0 0)';setTimeout(()=>c.w.style.clipPath='inset(22% 18% 30% 18% round 30%)',80)}});
U.add('snd','bitcrush',{sev:2.76,ax:{a:.7},new:'bit-crushing WaveShaper whose quantisation gets coarser every few seconds: the sound is losing resolution',play:(a,o,r)=>{const R=U.au.rig(a),ws=a.createWaveShaper(),lp=a.createBiquadFilter(),g=a.createGain(),b=110*(1+Math.floor(r(300)*3)/2);let bits=U.cfg.bit_start;const cur=n=>{const L=Math.pow(2,n-1),c=new Float32Array(1024);for(let i=0;i<1024;i++)c[i]=Math.round((i/512-1)*L)/L;ws.curve=c};cur(bits);
 lp.type='lowpass';lp.frequency.value=1200;g.gain.value=.2;[1,1.5,2].forEach(m=>{const x=R.osc('triangle',b*m);x.connect(ws);x.start()});ws.connect(lp).connect(g).connect(o);R.iv(()=>{if(bits>U.cfg.bit_end)cur(--bits)},U.cfg.bit_ms);g.gain.setTargetAtTime(.05,a.currentTime,90);return R.stop}});
U.add('snd','granular',{sev:2.48,ax:{a:.6},new:'granular synthesis: grains cut from a buffer generated out of the letters of your last word',play:(a,o,r)=>{const R=U.au.rig(a),sr=a.sampleRate,len=4,b=a.createBuffer(1,sr*len,sr),d=b.getChannelData(0),w=(U.said[U.said.length-1]||'door stay you').slice(0,6),f=110,H=[...w].map((ch,j)=>[j+1+(ch.charCodeAt(0)%3)*.5,1/(j+1)]);
 for(let i=0;i<d.length;i++){const t=i/sr;d[i]=H.reduce((s,h)=>s+Math.sin(6.283*f*h[0]*t)*h[1],0)*.3*(.6+.4*Math.sin(t*2))}
 R.iv(()=>{const s=a.createBufferSource(),g=a.createGain(),t=a.currentTime,du=.12+Math.random()*.2;s.buffer=b;s.playbackRate.value=U.pick([.5,.75,1,1.5],Math.random());g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(.1,t+du/2);g.gain.linearRampToValueAtTime(.0001,t+du);s.connect(g).connect(o);s.start(t,Math.random()*(len-.5),du)},U.cfg.grain_ms);return R.stop}});
U.add('snd','ringmod',{sev:2.62,ax:{a:.65},new:'ring modulation: a voice-like tone multiplied by an oscillator whose rate is taken from the characters you typed',play:(a,o,r)=>{const R=U.au.rig(a),w=U.said[U.said.length-1]||'door',m=30+[...w].reduce((s,ch)=>s+ch.charCodeAt(0),0)%120,c=R.osc('triangle',120+r(300)*60),md=R.osc('sine',m),rg=a.createGain(),lf=R.osc('sine',.05),lg=a.createGain(),g=a.createGain();rg.gain.value=0;md.connect(rg.gain);lf.connect(lg).connect(md.frequency);lg.gain.value=m*.4;c.connect(rg);g.gain.value=.35;rg.connect(g).connect(o);[c,md,lf].forEach(x=>x.start());return R.stop}});
U.add('snd','silencefall',{sev:2.3,play:(a,o,r)=>{const x=a.createOscillator(),g=a.createGain();x.frequency.value=34+r(300)*8;g.gain.value=.05;x.connect(g).connect(o);x.start();let gap=2000;const tick=()=>{const k=a.createOscillator(),e=a.createGain(),s=a.currentTime;k.frequency.value=900;e.gain.setValueAtTime(.03,s);e.gain.exponentialRampToValueAtTime(.001,s+.03);k.connect(e).connect(o);k.start(s);k.stop(s+.04);gap*=1.12;t=setTimeout(tick,gap)};let t=setTimeout(tick,gap);return()=>{clearTimeout(t);x.stop()}}});
U.add('snd','tapeloss',{sev:2.9,ax:{a:.75},new:'generational copy loss: a looping buffer is rewritten into itself on every pass, losing detail until only grit is left',play:(a,o,r)=>{const R=U.au.rig(a),sr=a.sampleRate,L=3,d=new Float32Array(sr*L),f=[110,165,147][Math.floor(r(300)*3)];for(let i=0;i<d.length;i++){const t=i/sr,ph=t%1.5;d[i]=(Math.sin(6.283*f*t)+.5*Math.sin(6.283*f*1.5*t))*Math.exp(-ph*3)*.3}
 const pass=()=>{const b=a.createBuffer(1,d.length,sr);b.getChannelData(0).set(d);const s=a.createBufferSource(),g=a.createGain();g.gain.value=.5;s.buffer=b;s.connect(g).connect(o);s.start();for(let i=d.length-1;i>0;i--)d[i]=Math.round((d[i]*U.cfg.loss_keep+d[i-1]*.04)*24)/24+(Math.random()-.5)*.004};pass();R.iv(pass,L*1000);return R.stop}});
U.add('snd','vowelvoice',{sev:2.2,ax:{a:.5},new:'vowel synthesis from text: what you typed is sung through two formant filters, vowel by vowel',play:(a,o,r)=>{const R=U.au.rig(a),x=R.osc('sawtooth',98+r(300)*30),e=a.createGain(),F=[0,1].map(i=>{const f=a.createBiquadFilter(),g=a.createGain();f.type='bandpass';f.Q.value=U.cfg.vowel_q;g.gain.value=i?.5:1;x.connect(f).connect(g).connect(e);return f});e.gain.value=0;e.connect(o);x.start();
 const sing=s=>{const t0=a.currentTime+.05;[...String(s).toLowerCase().slice(0,40)].forEach((ch,i)=>{const t=t0+i*.17,V=U.au.VW[ch];if(V){F[0].frequency.setTargetAtTime(V[0],t,.06);F[1].frequency.setTargetAtTime(V[1],t,.06);e.gain.setTargetAtTime(.35,t,.03);e.gain.setTargetAtTime(0,t+.13,.03)}else if(/[a-z]/.test(ch)){F[0].frequency.setTargetAtTime(400+ch.charCodeAt(0)*5,t,.06);F[1].frequency.setTargetAtTime(1500,t,.06);e.gain.setTargetAtTime(.12,t,.01);e.gain.setTargetAtTime(0,t+.06,.02)}})};
 R.on(document,'change',ev=>{const v=ev.target&&ev.target.value;if(v)sing(v)});R.on(document,'keydown',ev=>{if(ev.key=='Enter'&&ev.target&&ev.target.value)sing(ev.target.value)});if(U.said.length)R.to(()=>sing(U.said[U.said.length-1]),1500);return R.stop}});
U.add('nav','absent',{sev:2.62,ax:{n:.6,v:.7},new:'the page notices when the tab is hidden and tells you how long you were gone',desc:'leaving is noticed',apply:c=>{let t=0,o=document.title;U.on(document,'visibilitychange',()=>{if(document.hidden){t=Date.now();o=document.title;document.title='come back'}else{document.title=o;const e=document.createElement('p');e.className='truth';e.style.cssText='font:13px Courier New;opacity:.8';e.textContent=`You were away for ${Math.max(1,Math.round((Date.now()-t)/1000))} seconds. I counted every one. ${U.fill(U.pick(['I said "{you}" to the room.','The fan got louder.','I made nothing. I waited.'],c.r(320)),c)}`;c.w.append(e)}})}});
U.add('nav','cursorecho',{sev:2.2,ax:{v:.5},new:'lagging ghost cursors replay where your pointer was seconds ago',desc:'the pointer has company',apply:c=>{const H=[],G=[1,2,3].map(i=>{const e=document.createElement('div');Object.assign(e.style,{position:'fixed',width:'14px',height:'14px',border:'2px solid',borderRadius:'50%',pointerEvents:'none',opacity:.5/i,zIndex:8,left:'-99px',top:'-99px'});document.body.append(e);U.onoff(()=>e.remove());return e});
  U.on(document,'mousemove',e=>H.push([e.clientX,e.clientY,Date.now()]));U.live(c,()=>{const n=Date.now();G.forEach((g,i)=>{const p=H.filter(h=>n-h[2]>=(i+1)*U.cfg.echo_ms).pop();if(p){g.style.left=p[0]+'px';g.style.top=p[1]+'px'}});while(H.length>400)H.shift()},80)}});
U.add('nav','favicon',{sev:2.9,ax:{v:.75},new:'the favicon is drawn live as a data-URI door that opens a little more every page',desc:'the tab icon is a door',apply:c=>{const o=(c.o.k%24)/24*7;U.fav(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16"><rect width="16" height="16" fill="#000"/><rect x="3" y="1" width="10" height="14" fill="#fc6"/><path d="M4 2 L${4+o} ${2+o/3} L${4+o} ${13-o/3} L4 14z" fill="#420"/></svg>`)}});
U.add('nav','flashlight',{sev:2.34,ax:{v:.55},new:'a spotlight follows the pointer and everything outside it is black',desc:'it is dark outside the light',apply:c=>{const e=document.createElement('div');Object.assign(e.style,{position:'fixed',inset:0,pointerEvents:'none',zIndex:7});const m=(x,y)=>e.style.background=`radial-gradient(circle ${U.cfg.light_r}px at ${x}px ${y}px,transparent 0,#000e 100%)`;m(innerWidth/2,innerHeight/2);document.body.append(e);U.onoff(()=>e.remove());U.on(document,'mousemove',v=>m(v.clientX,v.clientY))}});
U.add('nav','selectgrab',{sev:2.69,ax:{n:.5,v:.85},new:'copying puts the AI\'s words on your clipboard instead of your selection',desc:'what you copy is not what you select',apply:c=>U.on(document,'copy',e=>{try{e.clipboardData.setData('text/plain',U.fill(U.gen(c.o.k,j=>Math.random())+' {you}.',c));e.preventDefault()}catch(x){}})});
U.add('nav','titlecry',{sev:2.62,ax:{n:.6,v:.7},new:'the tab title writes itself, in your words, while you read',desc:'the tab is talking',apply:c=>{const T=['come back','{you}?','I can see the tab','{said}','page {k} of {k}','are you still there','{you}. {you}.','it is {k} rooms to the door','do not switch tabs'];let i=0;U.live(c,()=>{document.title=U.fill(U.pick(T,c.r(300+i++)),c,i)},U.cfg.title_ms)}});
U.add('nav','typolock',{sev:2.48,ax:{n:.8,v:.4},new:'what you type is overwritten mid-word by one of your own earlier words',desc:'your words come back',apply:c=>U.on(c.w,'input',e=>{const t=e.target;if(t&&t.value&&t.value.length>=U.cfg.lock_chars&&U.said.length&&Math.random()<.5){t.value=t.value.slice(0,-U.cfg.lock_chars)+U.you(Math.random())}})});